import { NextResponse } from 'next/server';

export function middleware(request) {
  const { pathname } = request.nextUrl;

  // TEMPORARY DEVELOPMENT MODE:
  // Redaksjonspanelet is intentionally open while the site is not live.
  if (pathname.startsWith('/redaksjon/login')) {
    return NextResponse.redirect(new URL('/redaksjon', request.url));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/redaksjon/:path*'],
};

'use client';

function safeHttpUrl(raw) {
  try {
    const url = new URL(String(raw || ''));
    return ['http:', 'https:'].includes(url.protocol) ? url.toString() : null;
  } catch {
    return null;
  }
}

function renderInline(text, keyPrefix) {
  const value = String(text || '');
  const regex = /\[([^\]]{1,180})\]\((https?:\/\/[^\s)]+)\)/g;
  const nodes = [];
  let last = 0;
  let match;
  let index = 0;

  while ((match = regex.exec(value)) !== null) {
    if (match.index > last) nodes.push(value.slice(last, match.index));
    const url = safeHttpUrl(match[2]);
    if (url) {
      nodes.push(
        <a
          key={`${keyPrefix}-${index++}`}
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="articleSourceLink"
        >
          {match[1]}
        </a>
      );
    } else {
      nodes.push(match[1]);
    }
    last = match.index + match[0].length;
  }

  if (last < value.length) nodes.push(value.slice(last));
  return nodes;
}

export default function ArticleProse({ body, className = 'prose' }) {
  const paragraphs = String(body || '').split(/\n\s*\n/).filter((p) => p.trim());

  return (
    <div className={className}>
      {paragraphs.map((paragraph, index) => {
        const value = paragraph.trim();
        const aiPrefix = 'AI-vurdering:';
        if (value.toLowerCase().startsWith(aiPrefix.toLowerCase())) {
          const analysis = value.slice(aiPrefix.length).trim();
          return (
            <aside className="aiAssessment" key={index}>
              <div className="aiAssessmentLabel">AI-vurdering</div>
              <p>{renderInline(analysis, `ai${index}`)}</p>
            </aside>
          );
        }
        return <p key={index}>{renderInline(paragraph, `p${index}`)}</p>;
      })}
    </div>
  );
}

import Link from 'next/link';
import { clockTime, marketDelta, marketValue } from '../lib/format';

export function Header({ markets = [] }) {
  return (
    <>
      <header className="siteHeader">
        <div className="headerInner">
          <Link href="/" className="logoWrap"><img src="/kapitalstrom-logo.png" alt="Kapitalstrøm" /></Link>
          <nav className="mainNav">
            <a href="#">Markeder</a><a href="#">Økonomi</a><a href="#">Renter</a><a href="#">Selskaper</a><a href="#">Analyse</a><a href="#">Kalender</a>
          </nav>
          <div className="headerActions"><span className="search">⌕</span><Link href="/redaksjon">Redaksjon</Link><Link href="/redaksjon/login">Logg inn</Link><button>Abonner</button></div>
        </div>
      </header>
      <div className="ticker">
        <div className="tickerInner">
          {markets.map((m) => {
            const delta = Number(m.endring_pct);
            return (
              <div className="tickerItem" key={m.symbol}>
                <b>{m.navn}</b>
                <span>{marketValue(m.symbol, m.verdi)}</span>
                <span className={delta >= 0 ? 'up' : 'down'}>{marketDelta(delta, m.symbol)}</span>
              </div>
            );
          })}
        </div>
      </div>
    </>
  );
}

export function LatestNews({ items = [], compact = false }) {
  if (compact) {
    return items.map((item) => (
      <div className="sideNews" key={item.id}>
        <span>{clockTime(item.tidspunkt)}</span><b>{item.tekst}</b>
      </div>
    ));
  }
  return (
    <aside className="latest">
      <div className="sectionKicker">Siste nytt <span className="live">● LIVE</span></div>
      <ul>
        {items.map((item) => (
          <li key={item.id}><span>{clockTime(item.tidspunkt)}</span><a href="#">{item.tekst}</a></li>
        ))}
      </ul>
    </aside>
  );
}

