// Production redeploy trigger

function deploymentMeta() {
  return {
    vercel_env: process.env.VERCEL_ENV || null,
    git_commit: process.env.VERCEL_GIT_COMMIT_SHA
      ? process.env.VERCEL_GIT_COMMIT_SHA.slice(0, 7)
      : null,
    deepseek_key_present: Boolean(process.env.DEEPSEEK_API_KEY),
  };
}

export async function GET() {
  const apiKey = process.env.DEEPSEEK_API_KEY;

  // TEMPORARY DEVELOPMENT DIAGNOSTIC:
  // Redaksjonspanelet is intentionally open while the site is not live.
  // Never return the secret value itself.
  if (!apiKey) {
    return NextResponse.json({
      ok: false,
      step: 'env',
      message: 'DEEPSEEK_API_KEY mangler i denne deploymenten.',
      ...deploymentMeta(),
    }, {
      status: 500,
      headers: { 'Cache-Control': 'no-store' },
    });
  }

  try {
    const sql = db();
    await ensureRawItemScoringSchema(sql);
    const [row] = await sql`
      SELECT COUNT(*)::int AS pending
      FROM raw_items
      WHERE behandlet = false
    `;

    const balanceResponse = await fetch('https://api.deepseek.com/user/balance', {
      cache: 'no-store',
      headers: { Authorization: `Bearer ${apiKey}` },
    });
    const balanceBody = await balanceResponse.json().catch(() => null);

    if (!balanceResponse.ok) {
      return NextResponse.json({
        ok: false,
        step: 'deepseek-balance',
        status: balanceResponse.status,
        message: balanceBody?.error?.message || `DeepSeek svarte HTTP ${balanceResponse.status}`,
        pending: row?.pending ?? null,
        ...deploymentMeta(),
      }, { status: 200, headers: { 'Cache-Control': 'no-store' } });
    }

    if (balanceBody?.is_available === false) {
      return NextResponse.json({
        ok: false,
        step: 'deepseek-balance',
        status: 402,
        message: 'DeepSeek-kontoen har ikke tilgjengelig API-saldo.',
        pending: row?.pending ?? null,
        ...deploymentMeta(),
      }, { status: 200, headers: { 'Cache-Control': 'no-store' } });
    }

    const testResponse = await fetch('https://api.deepseek.com/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: 'deepseek-flash',
        thinking: { type: 'disabled' },
        messages: [
          { role: 'system', content: 'Svar kun med gyldig JSON.' },
          { role: 'user', content: 'Returner JSON nøyaktig som {"ok":true}.' },
        ],
        response_format: { type: 'json_object' },
        max_tokens: 40,
        stream: false,
      }),
    });
    const testBody = await testResponse.json().catch(() => null);

    if (!testResponse.ok) {
      return NextResponse.json({
        ok: false,
        step: 'deepseek-test-call',
        status: testResponse.status,
        message: testBody?.error?.message || `DeepSeek svarte HTTP ${testResponse.status}`,
        pending: row?.pending ?? null,
        ...deploymentMeta(),
      }, { status: 200, headers: { 'Cache-Control': 'no-store' } });
    }

    return NextResponse.json({
      ok: true,
      database: 'connected',
      deepseek: 'connected',
      balance_available: balanceBody?.is_available !== false,
      pending: row?.pending ?? 0,
      model: testBody?.model || 'deepseek-flash',
      ...deploymentMeta(),
    }, { headers: { 'Cache-Control': 'no-store' } });
  } catch (error) {
    return NextResponse.json({
      ok: false,
      step: 'server',
      message: error?.message || 'Ukjent serverfeil',
      ...deploymentMeta(),
    }, { status: 200, headers: { 'Cache-Control': 'no-store' } });
  }
}

import { runAutopilotStep } from '../../../../lib/autopilot/autopilot';
import { getEditorialSettings } from '../../../../lib/autopilot/editorial-settings';

export const dynamic = 'force-dynamic';
export const maxDuration = 300;

function authorized(request) {
  const secret = process.env.CRON_SECRET;
  if (!secret) return false;
  return request.headers.get('authorization') === `Bearer ${secret}`;
}

function osloContext(now = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Oslo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    hour12: false,
  }).formatToParts(now);

  const value = (type) => parts.find((part) => part.type === type)?.value || '';
  const hour = Number(value('hour') || -1);
  const slot = `${value('year')}-${value('month')}-${value('day')}T${String(hour).padStart(2, '0')}`;

  return { hour, slot };
}

export async function GET(request) {
  if (!authorized(request)) {
    return Response.json({ ok: false, error: 'unauthorized' }, { status: 401 });
  }

  const url = new URL(request.url);
  const runId = Number(url.searchParams.get('runId') || 0) || null;
  const discovery = url.searchParams.get('discovery') === '1';

  try {
    const settings = await getEditorialSettings();
    const oslo = osloContext();

    // Main kill switch: stop both new scheduled rounds and an already-running
    // scheduled round at the next step. Manual controls in /redaksjon still work.
    if (!settings.automationEnabled) {
      return Response.json({
        ok: true,
        skipped: true,
        reason: 'automation_disabled',
        stage: 'done',
        runId,
        osloHour: oslo.hour,
        settings,
        checkedAt: new Date().toISOString(),
      });
    }

    // Only start a brand-new scheduled editorial round from 06:00 through 23:59 Oslo time.
    // Existing runs may finish even if the clock crosses the boundary.
    if (!runId && (oslo.hour < 6 || oslo.hour > 23)) {
      return Response.json({
        ok: true,
        skipped: true,
        reason: 'outside_editorial_hours',
        stage: 'done',
        osloHour: oslo.hour,
        settings,
        checkedAt: new Date().toISOString(),
      });
    }

    const result = await runAutopilotStep({
      discovery,
      runId,
      mode: 'scheduled',
      scheduledSlot: runId ? null : oslo.slot,
    });

    return Response.json({
      ...result,
      scheduled: true,
      scheduledSlot: runId ? null : oslo.slot,
      settings,
      checkedAt: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Editorial autopilot cron failed', error);
    return Response.json({
      ok: false,
      error: String(error?.message || 'editorial autopilot failed').slice(0, 500),
    }, { status: 500 });
  }
}

import { syncNorgesBankFx } from '../../../../lib/sources/norges-bank';
import { syncNorgesBankPolicyRate } from '../../../../lib/sources/norges-bank-policy-rate';

export const dynamic = 'force-dynamic';
export const maxDuration = 60;

function authorized(request) {
  const secret = process.env.CRON_SECRET;
  if (!secret) return false;
  return request.headers.get('authorization') === `Bearer ${secret}`;
}

export async function GET(request) {
  if (!authorized(request)) {
    return Response.json({ ok: false, error: 'unauthorized' }, { status: 401 });
  }

  try {
    const [fx, policyRate] = await Promise.all([
      syncNorgesBankFx(),
      syncNorgesBankPolicyRate(),
    ]);
    return Response.json({
      ok: true,
      source: 'Norges Bank',
      fx: fx.map((r) => ({ symbol: r.symbol, value: r.latest, changePct: r.changePct })),
      policyRate,
      checkedAt: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Norges Bank sync failed', error);
    return Response.json({ ok: false, error: error?.message || 'sync failed' }, { status: 500 });
  }
}

